const BY_CODE: Record<string, CountryPath> = COUNTRY_PATHS.reduce(
  (acc, country) => {
    acc[country.code] = country;
    return acc;
  },
  {} as Record<string, CountryPath>
);

export function getCountry(code: string): CountryPath | undefined {
  return BY_CODE[code];
}
